function activityImageUrl(path){if(!path)return '';const value=String(path);return value.startsWith('data:image/jpeg;base64,')||value.startsWith('data:image/png;base64,')||value.startsWith('data:image/webp;base64,')?value:`/api/activity-image?path=${encodeURIComponent(value)}`}
async function compressActivityImage(file){const bitmap=await createImageBitmap(file),limit=2200,scale=Math.min(1,limit/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d',{alpha:false}).drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob;for(const quality of [.86,.76,.66]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=1300000)break}if(!blob||blob.size>1300000)throw new Error('Este print ficou grande demais. Tente recortar a imagem antes de anexar.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('Não consegui preparar esta imagem.'));reader.readAsDataURL(blob)})}
async function uploadActivityImage(file,collection='activities'){const dataUrl=await compressActivityImage(file);if(!cloudMode)return dataUrl;const [,image]=dataUrl.split(',');const response=await fetch('/api/activity-image',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({image,contentType:'image/jpeg',collection})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Não consegui enviar o print. Confira sua conexão e o armazenamento de imagens.');return result.path}
async function deleteActivityImage(path){if(!path||String(path).startsWith('data:image/')||!cloudMode)return;const response=await fetch('/api/activity-image',{method:'DELETE',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({path})});if(!response.ok)throw new Error('Não consegui remover a imagem do armazenamento.')}
