function setCloudStatus(label,state='saved'){const el=document.querySelector('#cloud-status');if(el){el.textContent=label;el.dataset.state=state}}
function save(){localStorage.setItem(STORE,JSON.stringify(data));if(!cloudMode||!cloudReady)return;clearTimeout(cloudSaveTimer);setCloudStatus('SINCRONIZANDO…','syncing');cloudSaveTimer=setTimeout(()=>{const snapshot=JSON.stringify(data);cloudSaveChain=cloudSaveChain.then(async()=>{const response=await fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot,credentials:'same-origin'});if(response.status===401){cloudReady=false;showAuthGate('Sua sessão terminou. Entre novamente para continuar sincronizando.');return}if(!response.ok)throw new Error('sync');setCloudStatus('TUDO SINCRONIZADO','saved')}).catch(()=>setCloudStatus('SEM SINCRONIA · DADOS LOCAIS PRESERVADOS','error'))},450)}
