function normalizeCloudData(remote){data={...initial,...remote};data.menuChoices={...legacyMenuChoices,...(data.menuChoices||{})};menuChoiceStore=data.menuChoices;for(const key of ['agenda','lugares','compras','listaCompras','shoppingPlan','sports','livros','curiosidades','receitas','metas','transacoes','checkins'])if(!Array.isArray(data[key]))data[key]=[];if(!Array.isArray(data.cardapio))data.cardapio=[];if(!Array.isArray(data.sportCatalog)){data.sportCatalog=SPORT_PRESETS.map(([name,category],i)=>({id:'sport-'+i,name,category,done:false}));data.sports.forEach(x=>{const old=data.sportCatalog.find(y=>y.name.toLowerCase()===String(x.sport||'').toLowerCase());if(old)old.done=true;else if(x.sport)data.sportCatalog.push({id:crypto.randomUUID(),name:x.sport,category:'Personalizados',done:true})})}data.sportCatalog=data.sportCatalog.filter(x=>String(x.name).toLowerCase()!=='outro esporte')}
async function loadCloudData(){
 const response=await fetch('/api/data',{credentials:'same-origin',cache:'no-store'});if(response.status===401){showAuthGate();return false}if(!response.ok)throw new Error('data');const result=await response.json(),seed=result.seed||window.MeuRitmoHyroxData||{};let needsSeedSync=false;
 if(result.data){const remote=result.data;normalizeCloudData(remote);if(!remote.hyroxPlan&&seed.hyroxPlan){data.hyroxPlan=seed.hyroxPlan;needsSeedSync=true}if(!remote.hyroxMenu&&seed.hyroxMenu){data.hyroxMenu=seed.hyroxMenu;needsSeedSync=true}data.menuChoices={...legacyMenuChoices,...(data.menuChoices||{})};menuChoiceStore=data.menuChoices;localStorage.setItem(STORE,JSON.stringify(data))}
 else{const hasLocal=Boolean(localStorage.getItem(STORE));if(hasLocal){for(const key of ['receitas','shoppingPlan','cardapio'])if(Array.isArray(seed[key])&&!data[key]?.length)data[key]=seed[key];if(!data.nutritionGoals)data.nutritionGoals=seed.nutritionGoals||{};data.hyroxPlan=seed.hyroxPlan||data.hyroxPlan;data.hyroxMenu=seed.hyroxMenu||data.hyroxMenu;menuChoiceStore=data.menuChoices;await migrateLocalActivityImages()}else normalizeCloudData(seed||data);localStorage.setItem(STORE,JSON.stringify(data));const upload=await fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),credentials:'same-origin'});if(!upload.ok)throw new Error('migration')}
 cloudReady=true;document.querySelector('#auth-gate').hidden=true;document.querySelector('#cloud-logout').hidden=false;setCloudStatus('TUDO SINCRONIZADO','saved');if(needsSeedSync||Object.keys(legacyMenuChoices).length)save();render();return true
}
