function chart(){let values=Array(5).fill(0);data.transacoes.filter(x=>x.type==='Saída').forEach(x=>{let d=new Date(x.date+'T12:00:00');if(d.getMonth()===today.getMonth()&&d.getFullYear()===today.getFullYear())values[Math.min(4,Math.floor((d.getDate()-1)/7))]+=Number(x.value)||0});let max=Math.max(...values,1);let pts=values.map((v,i)=>`${24+i*106},${145-(v/max)*112}`).join(' ');let area=`24,145 ${pts} 448,145`;return `<svg viewBox="0 0 470 165" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#9db79f" stop-opacity=".3"/><stop offset="1" stop-color="#9db79f" stop-opacity="0"/></linearGradient></defs><path d="M24 28H449 M24 68H449 M24 108H449 M24 145H449" stroke="#edf0ea" stroke-dasharray="3 4" fill="none"/><polygon points="${area}" fill="url(#fill)"/><polyline points="${pts}" fill="none" stroke="#76967d" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${24+i*106}" cy="${145-(v/max)*112}" r="3.5" fill="#fff" stroke="#76967d" stroke-width="2"/>`).join('')}</svg>`}
