function agendaRows(items){return items.length?`<div class="agenda-list">${items.map(a=>`<div class="agenda-row ${a.planSessionId?'agenda-plan-row':''}"><span class="time-chip ${eventColor(a)}">${fmtDate(a.date)}${a.time?' · '+esc(a.time):''}</span><div class="row-main"><strong>${esc(a.title)}</strong><small>${esc(a.note||a.category||'')}</small></div>${a.category?`<span class="tag ${eventColor(a)}">${esc(a.category)}</span>`:''}${a.planSessionId?`<button class="button secondary plan-agenda-action" data-plan-log="${esc(a.planSessionId)}">＋ Registrar treino</button>`:`<div class="row-actions"><button data-toggle="agenda" data-id="${a.id}" title="Concluir">${a.done?'✓':'○'}</button><button data-edit="agenda" data-id="${a.id}" aria-label="Alterar">✎</button><button data-delete="agenda" data-id="${a.id}">×</button></div>`}</div>`).join('')}</div>`:`<div class="empty"><span>☀</span><h3>Sem compromissos neste dia</h3><p>Deixe um espaço para algo especial.</p><button class="button primary" data-add="agenda">＋ Adicionar à agenda</button></div>`}function calendarMarkup(items){let y=agendaMonth.getFullYear(),m=agendaMonth.getMonth(),first=new Date(y,m,1),count=new Date(y,m+1,0).getDate(),offset=(first.getDay()+6)%7,monthLabel=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(agendaMonth),days=Array.from({length:offset},()=>'<span class="calendar-blank"></span>');for(let day=1;day<=count;day++){let key=dateKey(new Date(y,m,day)),events=items.filter(x=>x.date===key).sort((a,b)=>(a.time||'').localeCompare(b.time||''));days.push(`<button class="calendar-day ${key===agendaSelectedDate?'selected':''} ${key===dateKey(today)?'today':''}" data-calendar-date="${key}"><strong>${day}</strong>${events.slice(0,3).map(a=>`<span class="calendar-event ${eventColor(a)}">${a.time?esc(a.time)+' · ':''}${esc(a.title)}</span>`).join('')}${events.length>3?`<small class="calendar-more">+${events.length-3} mais</small>`:''}</button>`)}while(days.length%7)days.push('<span class="calendar-blank"></span>');let selected=items.filter(x=>x.date===agendaSelectedDate).sort((a,b)=>(a.time||'').localeCompare(b.time||''));return `<section class="card calendar-card"><div class="calendar-head"><div><span class="eyebrow">SUA AGENDA</span><h2>${monthLabel}</h2><p class="calendar-hint">Toque em um dia para ver os detalhes e registrar os treinos planejados.</p></div><div class="calendar-controls"><button class="icon-button" data-month-shift="-1" aria-label="Mês anterior">‹</button><button class="icon-button" data-month-shift="1" aria-label="Próximo mês">›</button></div></div><div class="calendar-grid calendar-weekdays">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${days.join('')}</div></section><div class="section-heading"><div><h2>${new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(new Date(agendaSelectedDate+'T12:00:00'))}</h2><p>${selected.length} compromisso${selected.length===1?'':'s'} · eventos coloridos para facilitar a leitura</p></div><button class="button primary" data-add="agenda">＋ Novo compromisso</button></div>${agendaRows(selected)}`}function sportCatalogMarkup(){let all=data.sportCatalog||[],visible=all.filter(x=>(sportCatalogFilter==='Todos'||(sportCatalogFilter==='Já fiz'?x.done:!x.done))&&(!search||JSON.stringify(x).toLowerCase().includes(search.toLowerCase()))),groups={};visible.forEach(x=>(groups[x.category||'Outros']??=[]).push(x));let done=all.filter(x=>x.done).length;return `<div class="sport-catalog-intro"><div><span class="eyebrow">SUA LISTA DE MODALIDADES</span><h2>${done} de ${all.length} esportes já experimentados</h2><p>Marque o que você já fez. As atividades registradas também são marcadas automaticamente.</p></div><button class="button primary" data-add="sportCatalog">＋ Adicionar esporte</button><div class="progress"><span style="width:${all.length?done/all.length*100:0}%"></span></div></div><div class="sports-catalog-controls"><div class="filter-tabs">${['Todos','Quero fazer','Já fiz'].map(x=>`<button class="${sportCatalogFilter===x?'active':''}" data-sport-filter="${x}">${x}</button>`).join('')}</div><span>${visible.length} modalidades</span></div>${Object.keys(groups).length?Object.entries(groups).map(([category,rows])=>`<section class="sport-category"><h3>${esc(category)} <span>${rows.length}</span></h3><div class="sport-catalog-grid">${rows.map(x=>`<article class="card sport-catalog-item ${x.done?'is-done':''}"><button class="sport-check ${x.done?'checked':''}" data-sport-toggle="${x.id}" aria-label="${x.done?'Marcar como quero fazer':'Marcar como já fiz'}">${x.done?'✓':'○'}</button><div><strong>${esc(x.name)}</strong><small>${x.done?'Já fiz':'Quero fazer'}</small></div><div class="row-actions"><button data-edit="sportCatalog" data-id="${x.id}" aria-label="Alterar esporte">✎</button><button data-delete="sportCatalog" data-id="${x.id}" aria-label="Remover esporte">×</button></div></article>`).join('')}</div></section>`).join(''):`<div class="empty"><span>↗</span><h3>Nenhum esporte nesta lista</h3><p>Inclua outra modalidade ou mude o filtro.</p><button class="button primary" data-add="sportCatalog">＋ Adicionar esporte</button></div>`}`}
function safeHttp(url){try{let u=new URL(url);return ['http:','https:'].includes(u.protocol)?esc(u.href):''}catch{return ''}}
function placeImage(x){if(x.photoPath)return activityImageUrl(x.photoPath);try{const image=new URL(x.photoUrl);return ['http:','https:'].includes(image.protocol)?image.href:''}catch{return ''}}
function placeDetailMarkup(x){let link=safeHttp(x.url),image=placeImage(x);return `<button class="back-link" data-place-back>← Voltar aos destinos</button><div class="place-detail-hero ${image?'has-place-image':''}">${image?`<img src="${esc(image)}" alt="Foto de ${esc(x.name)}">`:''}<div class="place-detail-copy"><span class="eyebrow">${esc(x.kind||'DESTINO')}</span><h1>${esc(x.name)}</h1><p>${esc(x.region||'')}</p></div>${image?'':'<div class="place-detail-symbol">◎</div>'}</div><div class="place-detail-actions"><button class="button secondary" data-edit="lugares" data-id="${x.id}">✎ Alterar destino</button><button class="button secondary" data-delete="lugares" data-id="${x.id}">× Excluir</button></div><div class="place-detail-grid"><section class="card place-detail-main"><span class="eyebrow">O QUE VOCÊ QUER CONHECER</span><h2>${esc(x.description||'Ainda não adicionou detalhes sobre este destino.')}</h2>${x.note?`<p>${esc(x.note)}</p>`:''}${x.tips?`<div class="place-info-block"><strong>Dicas e informações</strong><p>${esc(x.tips)}</p></div>`:''}${link?`<a class="button secondary" href="${link}" target="_blank" rel="noopener">Abrir link de referência ↗</a>`:''}</section><section class="card place-detail-facts"><h3>Seu plano de viagem</h3>${x.visitWhen?`<div><small>QUANDO IR</small><strong>${esc(x.visitWhen)}</strong></div>`:''}${x.duration?`<div><small>DURAÇÃO</small><strong>${esc(x.duration)}</strong></div>`:''}${x.budget?`<div><small>ORÇAMENTO ESTIMADO</small><strong>${money(x.budget)}</strong></div>`:''}${!x.visitWhen&&!x.duration&&!x.budget?'<p class="card-subtitle">Adicione época, duração e orçamento para planejar sua visita.</p>':''}</section></div>`}function shoppingPlanMarkup(){let all=data.shoppingPlan||[],visible=all.filter(x=>(shoppingPlanFilter==='Todas'||x.category===shoppingPlanFilter)&&(!shoppingPlanSearch||JSON.stringify(x).toLocaleLowerCase('pt-BR').includes(shoppingPlanSearch.toLocaleLowerCase('pt-BR')))),categories=['Todas',...new Set(all.map(x=>x.category))],sum=all.reduce((n,x)=>n+(Number(x.subtotal)||0),0),doneSum=all.filter(x=>x.done).reduce((n,x)=>n+(Number(x.subtotal)||0),0),proteins=all.filter(x=>String(x.category).toLocaleLowerCase('pt-BR').includes('proteína')).length;return `<div class="meal-plan-head"><div><span class="eyebrow">SUA LISTA DO PLANO ALIMENTAR</span><h2>Proteínas e compras da semana</h2><p>${all.length} itens · ${proteins} itens de proteínas e laticínios</p></div><button class="button primary" data-add="shoppingPlan">＋ Adicionar item</button></div><div class="shopping-total-card"><div><span>VALOR TOTAL ESTIMADO</span><strong>${money(sum)}</strong><small>Estimativa da lista completa</small></div><div><span>JÁ MARCADO NO CARRINHO</span><strong>${money(doneSum)}</strong><small>${all.filter(x=>x.done).length} de ${all.length} itens</small></div><div class="shopping-total-progress"><div class="progress"><span style="width:${all.length?all.filter(x=>x.done).length/all.length*100:0}%"></span></div><small>Progresso da compra</small></div></div><div class="meal-plan-search"><input id="shopping-plan-search" type="search" value="${esc(shoppingPlanSearch)}" placeholder="Buscar proteína, alimento ou tempero..."></div><p class="meal-plan-note">Preços e quantidades vieram do seu arquivo e podem ser alterados. Marque os itens conforme colocar no carrinho.</p><div class="plan-category-tabs">${categories.map(c=>`<button class="${shoppingPlanFilter===c?'active':''}" data-plan-category="${esc(c)}">${esc(c)}</button>`).join('')}</div>${visible.length?`<div class="shopping-list">${visible.map(x=>`<div class="purchase-row ${x.done?'plan-item-done':''}"><button class="check ${x.done?'done':''}" data-toggle="shoppingPlan" data-id="${x.id}">${x.done?'✓':''}</button><div class="row-main"><strong>${esc(x.name)}</strong><small>${esc(x.category)} · ${esc(x.quantity)} ${esc(x.unit)}${x.unitPrice?' · '+money(x.unitPrice)+' / '+esc(x.unit):''}${x.note?' · '+esc(x.note):''}</small></div><span class="row-meta">${money(x.subtotal)}</span><div class="row-actions"><button data-edit="shoppingPlan" data-id="${x.id}" aria-label="Alterar item">✎</button><button data-delete="shoppingPlan" data-id="${x.id}" aria-label="Excluir item">×</button></div></div>`).join('')}</div>`:`<div class="empty"><span>☷</span><h3>Nenhum item nesta categoria</h3><p>Escolha outra categoria ou adicione um novo item.</p><button class="button primary" data-add="shoppingPlan">＋ Adicionar item</button></div>`}`}function cardapioMarkup(){const days=data.cardapio||[],goals=data.nutritionGoals||{};if(!days.length)return '<div class="empty"><span>♧</span><h3>Cardápio ainda não carregado</h3><p>Atualize a página para importar o plano semanal.</p></div>';const day=days[menuDayIndex]||days[0],dayKey=day.day,defaultOption=String(day.meals[0]?.option||'A').charAt(0),selected=menuChoiceStore[dayKey]||defaultOption,plans={};days.forEach(d=>{const key=String(d.meals[0]?.option||'A').charAt(0);if(!plans[key])plans[key]=d.meals});const plan=plans[selected]||day.meals;const meals=day.meals.map(base=>{const entry=plan.find(m=>m.name===base.name)||base;return {...entry,option:base.option}});return `<div class="page-heading"><span class="eyebrow">SEU PLANO DA SEMANA</span><h1>Cardápio</h1><p>Refeições organizadas por dia. Escolha a opção de preparo que combina com você.</p></div><div class="nutrition-goals">${Object.entries(goals).filter(([key])=>key!=='Observação').map(([key,value])=>`<div class="card nutrition-goal"><small>${esc(key)}</small><strong>${esc(value)}</strong></div>`).join('')}</div><div class="card menu-planner"><div class="menu-days">${days.map((d,i)=>`<button class="menu-day ${i===menuDayIndex?'active':''}" data-menu-day="${i}">${esc(d.day)}</button>`).join('')}</div><div class="menu-title"><div><span class="eyebrow">PLANO DO DIA</span><h2>${esc(day.day)}</h2></div><span class="tag">${meals.length} refeições</span></div><div class="menu-options"><span>Opção do dia</span>${Object.keys(plans).sort().map(key=>`<button class="${key===selected?'active':''}" data-menu-option="${key}" aria-pressed="${key===selected}">Opção ${key}</button>`).join('')}</div><div class="menu-meals">${meals.map(meal=>`<article class="card meal"><div class="meal-top"><h3>${esc(meal.name)}</h3><span class="meal-tag">${String(meal.option).toLowerCase().includes('bike')?'Bike':`Opção ${selected}`}</span></div><p class="food">${esc(meal.foods)}</p>${meal.seasoning?`<div class="seasoning">Tempero: ${esc(meal.seasoning)}</div>`:''}</article>`).join('')}</div>${goals.Observação?`<p class="menu-note">${esc(goals.Observação)}</p>`:''}</div>`}

function planWeeks(){return [
 {id:'pre',name:'Pré-ciclo',dates:'26/10–1/11',start:'2026-10-26',days:{4:[['Escada','Condicionamento HYROX','Escada 4 × 3 min. Ritmo controlado, descansando conforme necessário.']],5:[['Corrida','Corrida/caminhada 2 min / 1 min × 7','21 min totais · esforço fácil 4–5/10.']]}},
 {id:'zero',name:'Semana 0',dates:'2–8/11',start:'2026-11-02',days:{0:[['Escada + técnica','Condicionamento HYROX','Escada 4 × 3 min.']],1:[['Técnica de wall ball + mobilidade','Condicionamento HYROX','Prática leve de técnica e mobilidade.']],2:[['Corrida','Corrida/caminhada 2 min / 1 min × 8','24 min totais · esforço fácil 4–5/10.']],3:[['Superiores B','Musculação','Semana de adaptação: 2 séries leves de cada exercício.']],4:[['Inferiores B','Musculação','Semana de adaptação: 2 séries leves de cada exercício.']],5:[['Corrida','Corrida/caminhada 3 min / 1 min × 5','20 min totais · esforço fácil 4–5/10.']]}},
 {id:'w1',name:'Semana 1',dates:'9–15/11',start:'2026-11-09',days:{0:[['Corrida','Corrida','3 min correndo / 1 min caminhando × 5 · 20 min.'],['Superiores A','Musculação','Treino de empurrar · consulte a ficha abaixo.']],1:[['Inferiores A','Musculação','Força de pernas · consulte a ficha abaixo.']],2:[['Escada + wall balls','Condicionamento HYROX','4 rounds: 2 min escada + 6 wall balls + 1 min caminhando.'],['Superiores B','Musculação','Costas, postura e pegada · consulte a ficha abaixo.']],4:[['Inferiores B','Musculação','Volume moderado · consulte a ficha abaixo.']],5:[['Corrida longa fácil','Corrida','3 min correndo / 1 min caminhando × 6 · 24 min.'],['Ombro e braço · opcional','Musculação','Opcional nas semanas 1–2; faça só se estiver recuperada.']]}},
 {id:'w2',name:'Semana 2',dates:'16–22/11',start:'2026-11-16',days:{0:[['Corrida','Corrida','3 min correndo / 1 min caminhando × 6 · 24 min.'],['Superiores A','Musculação','Treino de empurrar · consulte a ficha abaixo.']],1:[['Inferiores A','Musculação','Força de pernas · consulte a ficha abaixo.']],2:[['Escada + wall balls','Condicionamento HYROX','4 rounds: 2 min escada + 6 wall balls + 1 min caminhando.'],['Superiores B','Musculação','Costas, postura e pegada · consulte a ficha abaixo.']],4:[['Inferiores B','Musculação','Volume moderado · consulte a ficha abaixo.']],5:[['Corrida longa fácil','Corrida','4 min correndo / 1 min caminhando × 5 · 25 min.'],['Ombro e braço · opcional','Musculação','Opcional nas semanas 1–2; faça só se estiver recuperada.']]}},
 {id:'w3',name:'Semana 3',dates:'23–29/11',start:'2026-11-23',days:{0:[['Corrida','Corrida','4 min correndo / 1 min caminhando × 5 · 25 min.'],['Superiores A','Musculação','Treino de empurrar · consulte a ficha abaixo.']],1:[['Inferiores A','Musculação','Força de pernas · consulte a ficha abaixo.']],2:[['Escada + wall balls','Condicionamento HYROX','5 rounds: 2 min escada + 8 wall balls + 1 min caminhando.'],['Superiores B','Musculação','Costas, postura e pegada · consulte a ficha abaixo.']],4:[['Inferiores B','Musculação','Volume moderado · consulte a ficha abaixo.']],5:[['Corrida longa fácil','Corrida','5 min correndo / 1 min caminhando × 5 · 30 min.'],['Ombro e braço','Musculação','Recomendado se sono e pernas estiverem bem.']]}},
 {id:'w4',name:'Semana 4 · recuperação',dates:'30/11–6/12',start:'2026-11-30',days:{0:[['Corrida · volume reduzido','Corrida','3 min correndo / 1 min caminhando × 5 · 20 min.'],['Superiores A','Musculação','Mantenha as cargas e reduza as séries conforme a ficha.']],1:[['Inferiores A','Musculação','Mantenha as cargas e reduza as séries conforme a ficha.']],2:[['Escada + wall balls','Condicionamento HYROX','3 rounds: 2 min escada + 6 wall balls + 1 min caminhando.'],['Superiores B','Musculação','Mantenha as cargas e reduza as séries conforme a ficha.']],4:[['Inferiores B','Musculação','Mantenha as cargas e reduza as séries conforme a ficha.']],5:[['Teste leve de corrida','Corrida','5/12 · corra 20 min em ritmo fácil e contínuo se possível; caminhe 1 min se precisar. Registre distância, ritmo e FC média.'],['Ombro e braço','Musculação','Faça apenas se sono e pernas estiverem bem.']]}}
]}
function currentPlanWeek(){const weeks=planWeeks(),todayKey=today.toISOString().slice(0,10);let index=-1;weeks.forEach((week,i)=>{const next=weeks[i+1]?.start||'2026-12-07';if(todayKey>=week.start&&todayKey<next)index=i});return index>=0?index:(todayKey<weeks[0].start?0:weeks.length-1)}function plannedSessions(weekIndex=Number.isInteger(trainingWeek)?trainingWeek:currentPlanWeek()){const week=planWeeks()[weekIndex]||planWeeks()[0],base=new Date(week.start+'T12:00:00'),days=['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'];return days.map((day,i)=>{const date=new Date(base);date.setDate(base.getDate()+i);const entries=week.days[i]||[];return {day,date:date.toISOString().slice(0,10),items:entries.map(([title,sport,description],j)=>({id:`${week.id}-${i}-${j}`,title,sport,description,date:date.toISOString().slice(0,10)}))}})}
function agendaPlanEvents(){const logged=new Set((data.sports||[]).map(x=>x.planSessionId).filter(Boolean));return planWeeks().flatMap((week,index)=>plannedSessions(index).flatMap(day=>day.items.filter(item=>!logged.has(item.id)).map(item=>({...item,id:'plan-'+item.id,planSessionId:item.id,category:'Plano HYROX',note:item.sport+' · '+item.description}))))}
function hyroxCheckinMarkup(){const items=[...(data.checkins||[])].sort((a,b)=>(b.date||'').localeCompare(a.date||'')),weights=items.filter(x=>x.weight&&(!x.type||x.type==='Check-in semanal')).slice(0,3).map(x=>Number(x.weight)),average=weights.length?weights.reduce((a,b)=>a+b,0)/weights.length:null;return `<section class="plan-checkins card"><div class="checkin-head"><div><span class="eyebrow">ACOMPANHAMENTO DO CICLO</span><h2>Check-in e medidas</h2><p>Registre peso, sono, energia e dores semanalmente. Medidas corporais a cada 4 semanas.</p></div><button class="button primary" data-add="checkins">＋ Registrar check-in</button></div><div class="checkin-summary"><strong>${average===null?'—':average.toLocaleString('pt-BR',{maximumFractionDigits:1})+' kg'}</strong><span>média das últimas ${weights.length} pesagens registradas</span><small>Referência inicial do plano: 64 kg · pese-se 3 manhãs por semana em jejum.</small></div>${items.length?`<div class="checkin-list">${items.slice(0,5).map(x=>`<div class="checkin-row"><div><strong>${esc(x.type||'Check-in semanal')}</strong><small>${fmtDate(x.date)}${x.weight?' · '+esc(x.weight)+' kg':''}${x.sleepHours?' · sono '+esc(x.sleepHours)+' h':''}${x.pain?' · dor '+esc(x.pain)+'/10':''}${x.energy?' · energia '+esc(x.energy)+'/10':''}</small>${x.notes?`<p>${esc(x.notes)}</p>`:''}</div><div class="row-actions"><button data-edit="checkins" data-id="${x.id}" aria-label="Alterar check-in">✎</button><button data-delete="checkins" data-id="${x.id}" aria-label="Excluir check-in">×</button></div></div>`).join('')}</div>`:'<p class="card-subtitle">Ainda não há check-ins. O primeiro registro estabelece sua referência para acompanhar o ciclo.</p>'}</section>`}
function hyroxPlanMarkup(){const plan=data.hyroxPlan;if(!plan)return '<div class="empty"><h3>Plano HYROX não carregado</h3><p>Atualize os arquivos publicados para incluir o ciclo de treino.</p></div>';const weeks=planWeeks(),activeWeek=Number.isInteger(trainingWeek)?Math.max(0,Math.min(trainingWeek,weeks.length-1)):currentPlanWeek(),selected=weeks[activeWeek],schedule=plannedSessions(activeWeek),logged=new Set((data.sports||[]).map(x=>x.planSessionId).filter(Boolean));const running=plan.running||[],strength=plan.strength||[];return `<div class="page-heading"><span class="eyebrow">SUA PREPARAÇÃO · ${esc(plan.eventLabel)}</span><h1>Plano HYROX</h1><p>${esc(plan.goal)}</p></div><div class="plan-hero"><div><span class="eyebrow">CICLO 1 · BASE</span><h2>${esc(plan.cycleStart.split('-').reverse().join('/'))} a ${esc(plan.cycleEnd.split('-').reverse().join('/'))}</h2><p>Use a semana abaixo como guia. Ao registrar uma sessão, o treino planejado vai junto para seu histórico de esportes.</p></div><span class="plan-event">🏁<small>HYROX SP<br>${esc(plan.eventDate.split('-').reverse().join('/'))}</small></span></div><div class="plan-targets">${(plan.targets||[]).map(([label,value])=>`<article class="card"><small>${esc(label)}</small><strong>${esc(value)}</strong></article>`).join('')}</div>${hyroxCheckinMarkup()}<section class="plan-section"><div class="section-heading"><div><h2>Calendário do ciclo</h2><p>Escolha uma semana para ver as sessões planejadas.</p></div></div><div class="plan-week-tabs">${weeks.map((w,i)=>`<button class="${i===activeWeek?'active':''}" data-plan-week="${i}"><strong>${esc(w.name)}</strong><small>${esc(w.dates)}</small></button>`).join('')}</div><div class="plan-week-title"><h3>${esc(selected.name)}</h3><span>${esc(selected.dates)}</span></div><div class="plan-schedule">${schedule.map(day=>`<article class="card plan-day"><div class="plan-date"><strong>${esc(day.day)}</strong><small>${fmtDate(day.date)}</small></div><div class="plan-day-body">${day.items.length?day.items.map(s=>`<div class="planned-session"><div><span class="tag">${esc(s.sport)}</span><strong>${esc(s.title)}</strong><p>${esc(s.description)}</p></div>${logged.has(s.id)?'<span class="planned-done">✓ Registrado</span>':`<button class="button secondary" data-plan-log="${esc(s.id)}">Registrar sessão</button>`}</div>`).join(''):'<span class="rest-day">Recuperação / descanso</span>'}</div></article>`).join('')}</div></section><section class="plan-section"><div class="section-heading"><div><h2>Fichas de musculação</h2><p>Séries em cada semana: S1 · S2 · S3 · S4. Anote cargas e repetições no registro da atividade.</p></div></div><div class="plan-strength-grid">${strength.map(session=>`<details class="card strength-card"><summary><div><span class="eyebrow">${esc(session.day)} · ${esc(session.duration)}</span><h3>${esc(session.title)}</h3><p>${esc(session.objective)}</p></div><span class="strength-toggle">＋</span></summary><div class="strength-exercises">${['upper-b','lower-b'].includes(session.id)?'<p class="plan-note">Semana 0: 2 séries leves de cada exercício para aprender os movimentos e encontrar as cargas.</p>':''}<div class="strength-table-head"><span>Exercício</span><span>Séries</span><span>Reps</span></div>${session.exercises.map(([name,reps,sets])=>`<div class="strength-row"><span>${esc(name)}</span><strong>${esc(sets)}</strong><span>${esc(reps)}</span></div>`).join('')}<small>RIR do ciclo: sem. 0 = 4 · sem. 1 = 3 · sem. 2 = 2–3 · sem. 3 = 2 · sem. 4 = 3–4. Pare cada série com repetições sobrando.</small></div></details>`).join('')}</div></section><section class="plan-section plan-running"><div class="section-heading"><div><h2>Progressão de corrida</h2><p>Corrida fácil, esforço 4–5/10. Fale frases completas; caminhe mais se ficar ofegante.</p></div></div><div class="table-scroll"><table><thead><tr><th>Bloco</th><th>Segunda</th><th>Sábado</th><th>Tempo</th></tr></thead><tbody>${running.map(row=>`<tr><td><strong>${esc(row.week)}</strong><small>${esc(row.dates)}</small></td><td>${esc(row.monday)}</td><td>${esc(row.saturday)}</td><td>${esc(row.total)}</td></tr>`).join('')}</tbody></table></div><p class="plan-note">No teste leve de 5/12, anote tempo, distância, ritmo e frequência cardíaca média. Não é um esforço máximo.</p></section><section class="plan-section"><div class="section-heading"><div><h2>Escada, wall balls e mobilidade</h2><p>Quarta de manhã nas semanas 1–4; substitui a corrida de quarta neste ciclo.</p></div></div><div class="plan-station-grid">${(plan.stairs||[]).map(([week,detail,effort])=>`<article class="card"><span class="tag">${esc(week)}</span><p>${esc(detail)}</p><small>${esc(effort)}</small></article>`).join('')}</div><div class="card plan-mobility"><h3>Mobilidade diária · 5 min</h3><p>Peitoral na porta · rotação torácica · wall angel · alongamento do flexor do quadril · gato-camelo.</p><small>Faça numa pausa do trabalho ou pela manhã. Levante a cada 45–60 min sentado.</small></div></section><section class="plan-section"><div class="section-heading"><div><h2>Estações da prova</h2><p>Referências Open masculino que aparecem no plano. Confirme as cargas no regulamento oficial da sua prova.</p></div></div><div class="station-list">${(plan.stations||[]).map(([name,detail],i)=>`<article class="card"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(name)}</strong><small>${esc(detail)}</small></div></article>`).join('')}</div></section><section class="plan-section"><div class="section-heading"><div><h2>Regras para ajustar</h2><p>Cuide da recuperação e priorize a execução consistente.</p></div></div><div class="plan-safety">${(plan.safety||[]).map((rule,i)=>`<article class="plan-rule-card"><span>${String(i+1).padStart(2,'0')}</span><p>${esc(rule)}</p></article>`).join('')}</div></section><section class="plan-section"><div class="section-heading"><div><h2>Próximas fases</h2><p>O plano detalhado evolui com os dados reais de cada ciclo.</p></div></div><div class="plan-phase-grid">${(plan.phases||[]).map(phase=>`<article class="card"><span class="eyebrow">${esc(phase.period)}</span><h3>${esc(phase.name)}</h3><p>${esc(phase.focus)}</p></article>`).join('')}</div></section>`}
function hyroxMenuMarkup(){const menu=data.hyroxMenu;if(!menu)return '<div class="empty"><h3>Cardápio do ciclo não carregado</h3><p>Atualize os arquivos publicados para incluir as opções alimentares do Ciclo 1.</p></div>';const day=menu.weekly[menuDayIndex]||menu.weekly[0],runDays=new Set(['Segunda','Quarta','Sábado']),shown=menu.meals.filter(m=>m.id!=='preRun'||runDays.has(day.day));let totalKcal=0,totalProtein=0;const cards=shown.map(meal=>{const defaultKey=meal.id==='preRun'?day.preRun:day[meal.id],storedKey=menuChoiceStore[`${day.day}:${meal.id}`],selected=meal.id==='supper'?(storedKey||''):String(storedKey||defaultKey||meal.options[0][0]),option=meal.options.find(o=>o[0]===selected);if(option){totalKcal+=Number(option[2])||0;totalProtein+=Number(option[3])||0}return `<article class="card meal-choice"><div class="meal-choice-head"><div><span class="eyebrow">${esc(meal.time)}</span><h3>${esc(meal.name)}</h3></div><select data-meal-choice="${esc(meal.id)}" aria-label="Escolher ${esc(meal.name)}">${meal.id==='supper'?`<option value="" ${!selected?'selected':''}>Não incluir</option>`:''}${meal.options.map(o=>`<option value="${esc(o[0])}" ${selected===o[0]?'selected':''}>Opção ${esc(o[0])} · ${o[2]} kcal</option>`).join('')}</select></div>${option?`<p>${esc(option[1])}</p><div class="meal-macros"><span>${option[2]} kcal</span><span>${option[3]} g proteína</span></div>`:'<p class="meal-skipped">Ceia opcional. Selecione uma opção se quiser incluir.</p>'}</article>`}).join('');const totals=menu.weekly.map(d=>`<tr><td>${esc(d.day)}</td><td>${d.kcal.toLocaleString('pt-BR')} kcal</td><td>${d.protein} g</td></tr>`).join('');return `<div class="page-heading"><span class="eyebrow">ALIMENTAÇÃO · CICLO 1</span><h1>Cardápio HYROX</h1><p>Escolha uma opção por refeição. Os valores são estimativas do plano e mudam conforme as escolhas do dia.</p></div><div class="plan-targets nutrition-targets"><article class="card"><small>Meta de energia</small><strong>${esc(menu.goals.calories)}</strong></article><article class="card"><small>Proteína mínima</small><strong>${esc(menu.goals.protein)}</strong></article><article class="card"><small>Hidratação de referência</small><strong>${esc(menu.goals.water)}</strong></article><article class="card"><small>Variação de peso indicada</small><strong>${esc(menu.goals.weight)}</strong></article></div><div class="card nutrition-restrictions"><strong>Preferências consideradas no plano</strong><p>${esc(menu.restrictions)}</p></div><div class="menu-planner"><div class="menu-days">${menu.weekly.map((d,i)=>`<button class="menu-day ${i===menuDayIndex?'active':''}" data-menu-day="${i}">${esc(d.day)}</button>`).join('')}</div><div class="menu-title"><div><span class="eyebrow">SUGESTÃO DO PLANO · ${esc(day.day)}</span><h2>Suas refeições</h2></div><button class="button secondary" data-reset-menu-day>Restaurar sugestão do plano</button></div><div class="daily-menu-summary"><span>${totalKcal.toLocaleString('pt-BR')} kcal estimadas</span><span>${totalProtein} g de proteína</span></div><div class="menu-meals">${cards}</div><p class="menu-note">${esc(menu.restrictions)} As opções foram transcritas do seu plano. Ajustes de calorias, peso e suplementação devem seguir a orientação do profissional que acompanha você.</p></div><section class="plan-section"><div class="section-heading"><div><h2>Rotação semanal sugerida</h2><p>Estimativa diária do plano, sem ceia opcional. Você pode trocar opções acima.</p></div></div><div class="table-scroll"><table><thead><tr><th>Dia</th><th>Energia</th><th>Proteína</th></tr></thead><tbody>${totals}</tbody></table></div><p class="plan-note">Nos dias sem corrida, o lanche das 10h30 continua na sugestão. A ceia opcional soma cerca de 200 kcal.</p></section>`}
