 esportes:{title:'Registrar atividade',fields:[['sport','Qual esporte ou atividade?','text',true],['date','Dia em que fez','date',true],['time','Horário','time'],['workout','O que você fez? (ex.: treino X, passeio no parque)','textarea'],['duration','Duração (minutos)','number'],['distance','Distância (km)','number'],['pace','Pace ou ritmo (ex.: 5:40 min/km)','text'],['notes','Outras informações importantes','textarea'],['rpe','Esforço percebido (0–10)','number'],['heartRate','FC média (bpm)','number'],['pain','Dor ou desconforto (0–10)','number'],['activityImage','Adicionar print do Strava','file']]},
