 livros:{title:'Adicionar livro à estante',fields:[['title','Título do livro','text',true],['author','Autor','text'],['status','Status','select',['Quero ler','Lendo','Lido']],['progress','Quanto já leu? (%)','number'],['format','Formato ou gênero','text'],['rating','Sua nota (1 a 5)','number'],['notes','Anotações ou trechos favoritos','textarea']]},
 curiosidades:{title:'Guardar uma curiosidade',fields:[['title','O que você descobriu?','text',true],['category','Assunto','text'],['note','Por que quer guardar? Conte mais','textarea'],['url','Fonte ou link (opcional)','url'],['created','Data','date']]},
 receitas:{title:'Adicionar receita',fields:[['title','Nome da receita','text',true],['category','Categoria','text'],['time','Tempo de preparo','text'],['servings','Rendimento (porções)','number'],['ingredients','Ingredientes','textarea',true],['instructions','Modo de preparo','textarea',true],['url','Link da receita (opcional)','url'],['notes','Dicas e adaptações','textarea']]},
